"function olTerms(r){var out=[],i,t;for(i=0;i<r.terms.length&&out.length<OL_MAX;i++){t=sgwClean(r.terms[i]);if(t)out.push(t)}return out}",
"function olGet(id,t){var k=t.toLowerCase();return id==='shopgoodwill'?sgw.cache[k]:(lv[id]&&lv[id].cache[k])}",
"function olFetch(id,t,cb){if(id==='shopgoodwill')sgwFetch(t,cb);else lvFetch(id,t,cb)}",
