"}",
"function olChip(r,t,j){var u=olUrl(olSite(r),t);return '<li data-ol=\"'+j+'\"><a href=\"'+esc(u)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+olStar(t)+esc(t)+'</a></li>'}",
"function olSum(r){",
