"  for(i=0;i<T.length;i++){c=olGet(olSite(r),T[i]);if(!c){wait++;continue}if(c.err)continue;c=fltOnly(c.items).length;if(c){live++;n+=c}}",
"  return '<strong>'+r.terms.length+'</strong> hunts · '+(n?'<strong>'+n+'</strong> listing'+(n===1?'':'s')+' on <strong>'+live+'</strong> of them':wait?'checking':'nothing live right now')+",
"    (wait?' · '+FLY3+'checking '+wait+' more':'');",
"}",
