"  for(j=0;j<T.length;j++)if(olState(r,T[j])==='has')has+=olBlock(r,T[j],j);",
"  for(k=T.length;k<r.terms.length;k++)rest.push('<li><a href=\"'+esc(olUrl(olSite(r),r.terms[k]))+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(r.terms[k])+' ↗</a></li>');",
"  var sn=runSiteName(r),sto=r.mode==='store';",
