"    '<h2>'+olHead(r)+'</h2><p class=rs id=\"otp-olSum\">'+olSum(r)+'</p></div>'+",
"    '<div class=rh-acts><button class=\"gh dg-x\" id=otp-cr type=button aria-label=\"Close\">✕</button></div></div>'+(sto?storeBar(olSite(r)):'')+",
"    '<div id=\"otp-olHas\">'+has+'</div><div class=\"ol-rest\" id=\"otp-olNone\" hidden></div><div class=\"ol-rest\" id=\"otp-olErr\" hidden></div>'+",
"    (rest.length?'<div class=\"ol-rest\"><p class=\"ol-fh\">More hunts, open on '+esc(sn)+' <span>'+rest.length+'</span></p><ul>'+rest.join('')+'</ul></div>':'')+",
"    '<div class=oabar>'+(paused?'<button class=\"b p\" id=otp-next type=button>Open next '+Math.min(BATCH,left)+'</button>'",
"      :'<button class=\"b\" id=otp-oa type=button>Open all '+total+' on '+esc(sn)+'</button>')+'<small>Opens a tab per hunt. Allow pop-ups first.</small></div></div>';",
"  olFeet(r);",
"  if(sto)storeWire();",
"  var cr=$('#otp-cr');if(cr)cr.addEventListener('click',clearRun);",
