"  var nx=$('#otp-next');if(nx)nx.addEventListener('click',function(){launchNext(false)});",
"  if(!r.olGo){r.olGo=1;olFetchAll(r)}",
"}",
"function olHead(r){var n=r.terms.length;return (n===1?'Your hunt':'All '+n+' hunts')+' on '+esc(runSiteName(r))}",
