"    if(el){if(el.outerHTML!==tmp.innerHTML)box.replaceChild(tmp.firstChild,el)}",
"    else{nx=null;for(i=0;i<box.children.length;i++)if(+box.children[i].getAttribute('data-ol')>j){nx=box.children[i];break}box.insertBefore(tmp.firstChild,nx)}",
"  }else if(el)box.removeChild(el);",
