"function dgToday(){var d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}",
"function dgH(u){var h=5381,i;u=String(u);for(i=0;i<u.length;i++)h=((h*33)^u.charCodeAt(i))>>>0;return h.toString(36)}",
"function dgObj(x){return x&&typeof x==='object'&&Object.prototype.toString.call(x)!=='[object Array]'}",
