"    if(!dgObj(o))o={};if(!dgObj(o.cur))o.cur={};if(!dgObj(o.prev))o.prev={};if(!dgObj(o.cs))o.cs={};if(!dgObj(o.ps))o.ps={}}",
"  if(o.d!==t){if(o.d&&Object.keys(o.cur).length){o.pd=o.d;o.prev=o.cur;o.ps=o.cs}o.d=t;o.cur={};o.cs={}}",
