"}",
"function dgItems(k){",
"  var out=[],seen={},list=[sgw.cache[k]],i,j,c,it;",
"  for(i=0;i<LIVE_SRC.length;i++)list.push(lv[LIVE_SRC[i].id]&&lv[LIVE_SRC[i].id].cache[k]);",
"  for(i=0;i<list.length;i++){c=list[i];if(!c||c.err||!c.items)continue;",
"    for(j=0;j<c.items.length;j++){it=c.items[j];if(it&&it.url&&it.title&&!seen[it.url]){seen[it.url]=1;out.push(it)}}}",
"  return out;",
"}",
"function dgMark(k){",
