"function dgDayTick(){var o=null,t=dgToday();try{o=JSON.parse(localStorage.getItem(DG_DAYS_KEY)||'null')}catch(e){}if(!o||typeof o!=='object')o={d:'',n:0};if(o.d!==t){o.d=t;o.n=(Number(o.n)||0)+1;try{localStorage.setItem(DG_DAYS_KEY,JSON.stringify(o))}catch(e){}}}",
"function dgNew(T){",
