"  o.freq=PREF_FREQ[p.freq]?p.freq:'daily';",
"  o.sources=(p.sources&&p.sources.length)?p.sources.slice():PREF_SRC.map(function(s){return s[0]});",
"  if(!p.src2&&o.sources.indexOf('poshmark')===-1)o.sources.push('poshmark');",
"  if(!p.src3&&o.sources.indexOf('depop')===-1)o.sources.push('depop');",
"  if(!p.src4&&o.sources.indexOf('vinted')===-1)o.sources.push('vinted');",
"  if(!p.src5&&o.sources.indexOf('grailed')===-1)o.sources.push('grailed');",
"  o.src2=1;o.src3=1;o.src4=1;o.src5=1;",
