"  o.tz=browserTz()||tzOk(p.tz);",
"  o.zip=/^\\d{5}$/.test(String(p.zip||''))?String(p.zip):'';",
"  o.radius=PREF_RADII.indexOf(parseInt(p.radius,10))!==-1?parseInt(p.radius,10):50;",
"  o.local=(p.local||[]).map(function(h){return String(h).toLowerCase()});",
