"        '<div class=\"mail-in\">'+pncIn('avoid','Skip words: lamp, planter',d.avoid)+'</div><div class=\"mail-in\">'+pncIn('lo','Min price $',d.lo,'number')+pncIn('hi','Max price $',d.hi,'number')+'</div><div class=\"mail-in\">'+pncIn('min','Min inches',d.min,'number')+pncIn('max','Max inches',d.max,'number')+'</div><div class=\"mail-in\">'+pncIn('photo','Reference photo link',d.photo,'url')+'</div>'+",
