"    if(PNC.msg&&PNC.mk===k)h+=pncMsg();",
"  }",
"  for(k in q)if(!act[k]&&pncOn(q[k]))h+='<div class=\"mail-row\"><span class=\"nm\">'+esc(k)+' (paused)</span><button type=\"button\" class=\"tg\" data-pnc=\"del\" data-h=\"'+esc(k)+'\">Stop stalking</button></div>';",
