"  if(lvOld(c)&&!S.going[k]){delete S.cache[k];c=null}",
"  if(c){if(cb)cb(c);return}",
"  if(cb)(S.waiters[k]=S.waiters[k]||[]).push(cb);",
"  if(S.going[k]){",
