"function flockPick(t,n,dm){",
"  var k=t.toLowerCase(),prev=FLOCK.picks[k]||[],out=[],have=Object.create(null),used=Object.create(null),pool,i,p;",
"  for(i=0;i<prev.length&&out.length<n;i++){p=prev[i];if(!(dm&&dm[p.it.url])){out.push(p);have[p.it.url]=1;used[p.src]=1}}",
