"function gdMake(subject){",
"  subject=String(subject||'').replace(/\\s+/g,' ').replace(/^\\s+|\\s+$/g,'');",
"  if(GD.busy)return;",
"  if(aiOff()){gdNote('AI is turned off in your settings.');return}",
"  if(subject.length<2){gdNote('Type a subject first, like \\u201cFire-King jadeite\\u201d.');return}",
"  var at=gdIdx(subject);",
"  if(at>-1){gdRender(gdMine()[at]);gdNote('Opened from your saved guides.');return}",
"  if(typeof fetch!=='function'){gdNote('This browser cannot make guides.');return}",
"  gdBusy(true);",
"  gdNote('Researching the web for your guide. This can take up to a minute.');",
"  var body={subject:subject};",
"  if(mGet('alertTok')&&mGet('alertEmail')){body.e=mGet('alertEmail');body.t=mGet('alertTok')}",
"  var ctl=typeof AbortController==='function'?new AbortController():null,tm=setTimeout(function(){if(ctl)ctl.abort()},80000);",
"  var opt={method:'POST',headers:window.prowlAuth({'Content-Type':'application/json'}),body:JSON.stringify(body)};",
"  if(ctl)opt.signal=ctl.signal;",
"  fetch(SGW_API+'guide',opt).then(function(r){",
"    return r.json().then(function(j){return {s:r.status,j:j}},function(){return {s:r.status,j:null}});",
"  }).then(function(x){",
"    var j=x.j||{};",
"    if(x.s===200&&j.guide&&gdOk(j.guide)){",
"      gdRender(j.guide);",
"      gdNote(typeof j.left==='number'?(j.left+(j.pro?' ':' free ')+'guide'+(j.left===1?'':'s')+' left today.'+(j.pro?'':' Prowl Pro makes 15 a day.')):'');",
"    }",
"    else if(x.s===429&&j.error==='free limit')gdNote('You have used today\\u2019s '+(j.limit||3)+' free guides. They reset tomorrow, and Prowl Pro makes 15 a day.','/products/prowl-pro','Try Prowl Pro free for a month');",
"    else if(x.s===429&&j.error==='daily limit')gdNote('You have made today\\u2019s '+(j.limit||15)+' guides. They reset tomorrow.');",
"    else if(x.s===429)gdNote('Guides are busy right now. Try again in a little while.');",
"    else if(x.s===422)gdNote('That does not look like something collectors hunt. Try a maker, a line or a kind of object.');",
"    else if(x.s===400)gdNote('Try a plain subject, like \\u201cFire-King jadeite\\u201d.');",
"    else gdNote('Could not make that guide just now. Try again in a minute.');",
"  })['catch'](function(){gdNote('Could not make that guide just now. Try again in a minute.')}).then(function(){clearTimeout(tm);gdBusy(false)});",
"}",
