"function nrDayLabel(day){var m=/^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(day||'');return m?NR_D3[nrWeekday(day)]+' '+NR_MON[+m[2]-1]+' '+(+m[3]):''}",
"function nrTime(h,m){var ap=h>=12?'PM':'AM',hh=h%12||12;return hh+(m?':'+(m<10?'0':'')+m:'')+' '+ap}",
"function nrDayHours(hrs,day){",
"  if(!hrs||!hrs.periods)return {open:null,text:''};",
"  day=((day%7)+7)%7;",
"  var ps=[],i,p,d='',re=new RegExp('^'+NR_DAYS[day],'i'),t=[];",
"  for(i=0;i<hrs.periods.length;i++){p=hrs.periods[i];if(p&&p.open&&p.open.day===day)ps.push(p)}",
"  for(i=0;i<(hrs.days||[]).length;i++)if(re.test(hrs.days[i])){d=String(hrs.days[i]).replace(/^[A-Za-z]+:\\s*/,'').replace(/[  ]/g,' ');break}",
"  if(!ps.length){if(hrs.periods.length===1&&!hrs.periods[0].close)return {open:true,text:'Open 24 hours'};return {open:false,text:d||'Closed'}}",
"  if(d)return {open:true,text:d};",
"  for(i=0;i<ps.length;i++)t.push(nrTime(ps[i].open.hour,ps[i].open.minute)+(ps[i].close?'–'+nrTime(ps[i].close.hour,ps[i].close.minute):''));",
"  return {open:true,text:t.join(', ')};",
"}",
"function nrOpenAt(hrs,when){",
"  if(!hrs||!hrs.periods||!hrs.periods.length||hrs.offset==null)return null;",
"  var loc=new Date(when+hrs.offset*60000),day=loc.getUTCDay(),mins=loc.getUTCHours()*60+loc.getUTCMinutes(),i,p,o,c,t;",
"  for(i=0;i<hrs.periods.length;i++){",
"    p=hrs.periods[i];if(!p||!p.open)continue;if(!p.close)return true;",
"    o=p.open.day*1440+p.open.hour*60+p.open.minute;c=p.close.day*1440+p.close.hour*60+p.close.minute;t=day*1440+mins;",
"    if(c<=o)c+=10080;if(t<o)t+=10080;if(t>=o&&t<c)return true;",
"  }",
"  return false;",
"}",
"function nrNext(hrs,when){",
"  if(!hrs||!hrs.periods||!hrs.periods.length||hrs.offset==null)return null;",
"  var loc=new Date(when+hrs.offset*60000),t=loc.getUTCDay()*1440+loc.getUTCHours()*60+loc.getUTCMinutes(),i,p,o,c,x,d,best=null,bd=1e9;",
"  for(i=0;i<hrs.periods.length;i++){",
"    p=hrs.periods[i];if(!p||!p.open)continue;if(!p.close)return {open:true,always:true};",
"    o=p.open.day*1440+p.open.hour*60+p.open.minute;c=p.close.day*1440+p.close.hour*60+p.close.minute;if(c<=o)c+=10080;x=t<o?t+10080:t;",
"    if(x>=o&&x<c)return {open:true,close:p.close,left:c-x};",
"    d=(o-t+10080)%10080;if(d<bd){bd=d;best=p.open}",
"  }",
"  return best?{open:false,next:best,wait:bd,today:loc.getUTCDay()}:{open:false};",
"}",
"function nrHm(x){return nrTime(x.hour,x.minute)}",
"function nrNextText(n){",
"  if(!n)return '';",
"  if(n.always)return 'Open 24 hours';",
"  if(n.open)return 'Open until '+nrHm(n.close);",
"  if(!n.next)return 'Closed';",
"  if(n.next.day===n.today&&n.wait<1440)return 'Opens '+nrHm(n.next);",
"  if(n.next.day===(n.today+1)%7&&n.wait<2880)return 'Opens tomorrow '+nrHm(n.next);",
"  return 'Closed today · opens '+NR_D3[n.next.day]+' '+nrHm(n.next);",
"}",
"function nrState(hrs,day,eta){",
"  var now=Date.now(),today=nrLocalDay(new Date(now)),wd=day?nrWeekday(day):new Date(now).getDay(),dh=nrDayHours(hrs,wd),o,n,at;",
"  if(dh.open===null)return {cls:'',tag:'',text:'Hours not listed'};",
"  if(eta){",
