"    if(n&&n.open)return {cls:'nr-open',tag:'OPEN',text:at+' · '+nrNextText(n).replace(/^O/,'o')};",
"    if(n)return {cls:'nr-closed',tag:'CLOSED',text:at+' · '+(n.next&&n.next.day===n.today&&n.wait<1440?'opens '+nrHm(n.next):'closed by then')};",
"  }",
"  if(!day||day===today){",
"    n=nrNext(hrs,now);",
