"    o=nrOpenAt(hrs,now);if(o===true)return {cls:'nr-open',tag:'OPEN NOW',text:n?nrNextText(n):dh.text};if(o===false)return {cls:'nr-closed',tag:'CLOSED',text:n?nrNextText(n):dh.text};return {cls:'',tag:'',text:dh.text}",
"  }",
"  if(!dh.open)return {cls:'nr-closed',tag:'CLOSED',text:'Closed on '+NR_DAYS[wd]+'s'};",
"  return {cls:'nr-open',tag:'OPEN '+NR_D3[wd].toUpperCase(),text:dh.text};",
"}",
"function nrClock(ts){var d=new Date(Math.round(ts/300000)*300000);return nrTime(d.getHours(),d.getMinutes())}",
"function nrCard(p,day,cls,num,o){",
