"  return '<a class=\"nr-card'+(cls?' '+cls:'')+'\" href=\"'+esc(p.url||('https://www.google.com/maps/search/?api=1&query='+E(p.name+' '+(p.town||''))))+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+ph+",
"    '<span class=\"nr-body\">'+(o.been?'<span class=\"nr-beent\">✓ Been there</span>':'')+(p.pin?'<span class=\"nr-yours\">Your stop</span>':'')+'<b class=\"nr-n\">'+esc(p.name||'')+'</b><span class=\"nr-h'+(s.cls?' '+s.cls:'')+'\">'+esc(s.text)+'</span>'+nrRate(p)+'<span class=\"nr-t\">'+esc(p.town||'')+(p.why?' · '+esc(p.why):'')+'</span>'+(p.about?'<span class=\"nr-about\">'+esc(p.about)+'</span>':'')+nrPlanLine(p)+(o.off?'<span class=\"nr-nm\">Listed only, not in the Maps route</span>':'')+'</span>'+",
"    (s.tag||o.mi!=null||typeof o.det==='number'?'<span class=\"nr-side\">'+(s.tag?'<span class=\"nr-st '+s.cls+'\">'+s.tag+'</span>':'')+(o.mi!=null?'<span class=\"nr-mi\">'+nrMiTxt(o.mi)+'</span>':'')+(typeof o.det==='number'?'<span class=\"nr-det\" title=\"Adds about '+Math.max(1,Math.round(o.det))+' min to the drive\">+'+Math.max(1,Math.round(o.det))+' min</span>':'')+'</span>':'')+'</a>';",
"}",
"function nrDurT(m){return nrDur(m).replace(/\\s+$/,'')}",
"function nrPlanLine(p){var x=[];if(p.stay>0)x.push('Allow about '+nrDurT(p.stay));if(p.worth)x.push('Worth the detour');    if(p.walk)x.push('A short walk from the stop');return x.length?'<span class=\"nr-x\">'+esc(x.join(' · '))+'</span>':''}",
"function nrPlanSum(t,stops){var st=0,i;for(i=0;i<stops.length;i++)st+=stops[i].stay>0?stops[i].stay:0;if(!st||!t.route||!t.route.min)return '';var all=t.route.min+st;return '<p class=\"nearp nr-plan\">About '+nrDurT(st)+' in the shops. With the drive, '+nrDurT(all)+(all>600?': more than a day, so plan a night on the road or Skip a few stops.':'.')+'</p>'}",
"function nrMiFrom(you,p){if(!you||typeof p.lat!=='number'||typeof p.lng!=='number'||(!p.lat&&!p.lng))return null;var m=nrKm(you,p)*0.621371;return m<=150?m:null}",
"function nrMiTxt(m){return m<0.1?'< 0.1 mi':(m<10?(Math.round(m*10)/10):Math.round(m))+' mi'}",
"function nrPos(cb,fresh){",
"  if(!fresh&&NR.pos&&Date.now()-NR.posAt<300000){cb(NR.pos);return}",
