"function nrKm(a,b){var R=6371,dLat=(b.lat-a.lat)*Math.PI/180,dLng=(b.lng-a.lng)*Math.PI/180,s=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(a.lat*Math.PI/180)*Math.cos(b.lat*Math.PI/180)*Math.sin(dLng/2)*Math.sin(dLng/2);return 2*R*Math.asin(Math.min(1,Math.sqrt(s)))}",
"function nrDirUrl(p){var d=(p.name||'')+(p.town?', '+p.town:'');if(mapsPref()==='apple')return 'https://maps.apple.com/?daddr='+E(d)+'&dirflg=d';return 'https://www.google.com/maps/dir/?api=1&travelmode=driving&destination='+E(d)+(p.id?'&destination_place_id='+E(p.id):'')}",
