"  if(j.rating>0)h+='<p class=\"nr-rvh\"><span class=\"nr-stars\" aria-hidden=\"true\">'+nrStars(j.rating)+'</span> <b>'+Number(j.rating).toFixed(1)+'</b>'+(j.n?' · '+nrCount(j.n)+' reviews on Google Maps':'')+'</p>';",
"  if(j.about)h+='<p class=\"nearp\">'+esc(j.about)+'</p>';",
