"function nrGo(p){return '<a class=\"nr-go\" href=\"'+esc(nrDirUrl(p))+'\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Directions to '+esc(p.name||'')+'\">Directions</a>'}",
"function nrRow(p,day,num,o){return '<div class=\"nr-row\">'+nrCard(p,day,'',num,o)+'<span class=\"nr-acts\">'+nrGo(p)+nrRvBtn(p)+nrStopBtn(p)+'</span></div>'}",
"function nrStopTxt(p){return String((p.name||'')+(p.town?', '+p.town:'')).replace(/\\s+/g,' ').replace(/\\|/g,' ').trim().slice(0,120)}",
"function nrStopBtn(p){var v=p&&!p.pin?nrStopTxt(p):'';return v.length>=2?'<button type=\"button\" class=\"nr-addv\" data-nradd=\"'+esc(v)+'\" data-nraddid=\"'+esc(p.id||'')+'\" aria-label=\"Make '+esc(p.name||'')+' one of your stops on the way\">+ Stop</button>':''}",
