"    });",
"    if(pl){b.push([pl.lat,pl.lng]);L.circleMarker([pl.lat,pl.lng],{radius:9,weight:3,color:'#fff',fillColor:'#C2491F',fillOpacity:1}).addTo(m).bindPopup('<div class=\"nr-pop\"><b>'+esc(pl.town)+'</b><br><span>In a location</span></div>')}",
