"}",
"function nrMapToggle(mode){NR.mapOn[mode]=!NR.mapOn[mode];if(mode==='around')nrAroundDraw();else nrRedraw()}",
"var NR_BIRDS=[[18,22,0,3.6,4],[30,16,-.6,4.1,20],[12,18,-1.3,3.8,36],[42,13,-2,4.4,52],[26,15,-2.7,3.9,68]];",
"function nrFlock(id,stages){",
